window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-81e9948e5f9197f4"]={"versions": [{"id": "FIG-81e9948e5f9197f4", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt aus dem AUTOSAR Template Modeling Guide zur Illustration eines Modellierungsansatzes für Prototypen mit explizit modellierten Attributen (Alternative mit eigener PortPrototype-Entität am ComponentPrototype).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>ComponentType</code> («ARType»): Komponententyp, besitzt über eine Komposition mit Rollenbezeichnung <code>+port</code> und Multiplizität <code>*</code> Ports des Typs <code>PortPrototype</code>.\n</li><li><code>PortPrototype</code> («ARPrototype»): Repräsentiert die Port-Definition auf Typebene.\n</li><li><code>ComponentPrototype</code> («ARPrototype»): Prototyp einer Komponente. Steht in einer bidirektionalen Assoziation <code>«isOfType»</code> zu <code>ComponentType</code> (Rolle <code>+prototype</code> mit Multiplizität <code>*</code> auf Prototypseite, Rolle <code>+type</code> mit Multiplizität <code>1</code> auf Typseite).\n</li><li><code>PortPrototype2</code> («ARPrototype»): Explizit am <code>ComponentPrototype</code> modellierter Port-Prototyp, angebunden über eine Komposition mit Rolle <code>+port</code> und Kardinalität <code>*</code>.\n</li><li><code>ConnectorPrototype</code> («ARPrototype»): Verbindungs-Prototyp. Er referenziert direkt über eine gerichtete Assoziation <code>+port</code> mit Kardinalität <code>2</code> die Instanz <code>PortPrototype2</code>. Zusätzlich existiert eine gestrichelte Abhängigkeitsbeziehung <code>«instanceRef»</code> mit Rolle <code>+port</code> und Multiplizität <code>2</code> auf <code>PortPrototype</code>.\n</li><li>Invariante (<code>«Invariant»</code>): Gekoppelt an <code>PortPrototype2</code> mit der Bedingung <code>{&quot;ports of component prototype type must be consistent with ports of corresponding type&quot;}</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Architektur; kein dynamischer Sequenzablauf oder Laufzeitverhalten spezifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine Entwurfsvariante (Alternative) für das AUTOSAR-Metamodell dar, bei der Prototypen eigene, explizite Port-Prototyp-Instanzen (<code>PortPrototype2</code>) halten, anstatt Ports rein über Kontextpfade und Instanzreferenzen auf Typ-Ports abzubilden. Werkzeugentwickler und Modellierer müssen die Invariante beachten, wonach die an <code>ComponentPrototype</code> instanziierten Port-Prototypen zwingend konsistent zu den über <code>«isOfType»</code> assoziierten <code>PortPrototype</code>-Elementen des <code>ComponentType</code> gehalten werden müssen. Der Konnektor verbindet unmittelbar zwei <code>PortPrototype2</code>-Elemente und referenziert die typseitigen Ports via <code>«instanceRef»</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-06f17b44c95970be", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt aus dem AUTOSAR Template Modeling Guide zur Illustration eines Modellierungsansatzes für Prototypen mit explizit modellierten Attributen (Alternative mit eigener PortPrototype-Entität am ComponentPrototype).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>ComponentType</code> («ARType»): Komponententyp, besitzt über eine Komposition mit Rollenbezeichnung <code>+port</code> und Multiplizität <code>*</code> Ports des Typs <code>PortPrototype</code>.\n</li><li><code>PortPrototype</code> («ARPrototype»): Repräsentiert die Port-Definition auf Typebene.\n</li><li><code>ComponentPrototype</code> («ARPrototype»): Prototyp einer Komponente. Steht in einer bidirektionalen Assoziation <code>«isOfType»</code> zu <code>ComponentType</code> (Rolle <code>+prototype</code> mit Multiplizität <code>*</code> auf Prototypseite, Rolle <code>+type</code> mit Multiplizität <code>1</code> auf Typseite).\n</li><li><code>PortPrototype2</code> («ARPrototype»): Explizit am <code>ComponentPrototype</code> modellierter Port-Prototyp, angebunden über eine Komposition mit Rolle <code>+port</code> und Kardinalität <code>*</code>.\n</li><li><code>ConnectorPrototype</code> («ARPrototype»): Verbindungs-Prototyp. Er referenziert direkt über eine gerichtete Assoziation <code>+port</code> mit Kardinalität <code>2</code> die Instanz <code>PortPrototype2</code>. Zusätzlich existiert eine gestrichelte Abhängigkeitsbeziehung <code>«instanceRef»</code> mit Rolle <code>+port</code> und Multiplizität <code>2</code> auf <code>PortPrototype</code>.\n</li><li>Invariante (<code>«Invariant»</code>): Gekoppelt an <code>PortPrototype2</code> mit der Bedingung <code>{&quot;ports of component prototype type must be consistent with ports of corresponding type&quot;}</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Architektur; kein dynamischer Sequenzablauf oder Laufzeitverhalten spezifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine Entwurfsvariante (Alternative) für das AUTOSAR-Metamodell dar, bei der Prototypen eigene, explizite Port-Prototyp-Instanzen (<code>PortPrototype2</code>) halten, anstatt Ports rein über Kontextpfade und Instanzreferenzen auf Typ-Ports abzubilden. Werkzeugentwickler und Modellierer müssen die Invariante beachten, wonach die an <code>ComponentPrototype</code> instanziierten Port-Prototypen zwingend konsistent zu den über <code>«isOfType»</code> assoziierten <code>PortPrototype</code>-Elementen des <code>ComponentType</code> gehalten werden müssen. Der Konnektor verbindet unmittelbar zwei <code>PortPrototype2</code>-Elemente und referenziert die typseitigen Ports via <code>«instanceRef»</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-688bc7d97c331ceb", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt aus dem AUTOSAR Template Modeling Guide zur Illustration eines Modellierungsansatzes für Prototypen mit explizit modellierten Attributen (Alternative mit eigener PortPrototype-Entität am ComponentPrototype).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>ComponentType</code> («ARType»): Komponententyp, besitzt über eine Komposition mit Rollenbezeichnung <code>+port</code> und Multiplizität <code>*</code> Ports des Typs <code>PortPrototype</code>.\n</li><li><code>PortPrototype</code> («ARPrototype»): Repräsentiert die Port-Definition auf Typebene.\n</li><li><code>ComponentPrototype</code> («ARPrototype»): Prototyp einer Komponente. Steht in einer bidirektionalen Assoziation <code>«isOfType»</code> zu <code>ComponentType</code> (Rolle <code>+prototype</code> mit Multiplizität <code>*</code> auf Prototypseite, Rolle <code>+type</code> mit Multiplizität <code>1</code> auf Typseite).\n</li><li><code>PortPrototype2</code> («ARPrototype»): Explizit am <code>ComponentPrototype</code> modellierter Port-Prototyp, angebunden über eine Komposition mit Rolle <code>+port</code> und Kardinalität <code>*</code>.\n</li><li><code>ConnectorPrototype</code> («ARPrototype»): Verbindungs-Prototyp. Er referenziert direkt über eine gerichtete Assoziation <code>+port</code> mit Kardinalität <code>2</code> die Instanz <code>PortPrototype2</code>. Zusätzlich existiert eine gestrichelte Abhängigkeitsbeziehung <code>«instanceRef»</code> mit Rolle <code>+port</code> und Multiplizität <code>2</code> auf <code>PortPrototype</code>.\n</li><li>Invariante (<code>«Invariant»</code>): Gekoppelt an <code>PortPrototype2</code> mit der Bedingung <code>{&quot;ports of component prototype type must be consistent with ports of corresponding type&quot;}</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Architektur; kein dynamischer Sequenzablauf oder Laufzeitverhalten spezifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine Entwurfsvariante (Alternative) für das AUTOSAR-Metamodell dar, bei der Prototypen eigene, explizite Port-Prototyp-Instanzen (<code>PortPrototype2</code>) halten, anstatt Ports rein über Kontextpfade und Instanzreferenzen auf Typ-Ports abzubilden. Werkzeugentwickler und Modellierer müssen die Invariante beachten, wonach die an <code>ComponentPrototype</code> instanziierten Port-Prototypen zwingend konsistent zu den über <code>«isOfType»</code> assoziierten <code>PortPrototype</code>-Elementen des <code>ComponentType</code> gehalten werden müssen. Der Konnektor verbindet unmittelbar zwei <code>PortPrototype2</code>-Elemente und referenziert die typseitigen Ports via <code>«instanceRef»</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cb5e27a61dd5666b", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt aus dem AUTOSAR Template Modeling Guide zur Illustration eines Modellierungsansatzes für Prototypen mit explizit modellierten Attributen (Alternative mit eigener PortPrototype-Entität am ComponentPrototype).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>ComponentType</code> («ARType»): Komponententyp, besitzt über eine Komposition mit Rollenbezeichnung <code>+port</code> und Multiplizität <code>*</code> Ports des Typs <code>PortPrototype</code>.\n</li><li><code>PortPrototype</code> («ARPrototype»): Repräsentiert die Port-Definition auf Typebene.\n</li><li><code>ComponentPrototype</code> («ARPrototype»): Prototyp einer Komponente. Steht in einer bidirektionalen Assoziation <code>«isOfType»</code> zu <code>ComponentType</code> (Rolle <code>+prototype</code> mit Multiplizität <code>*</code> auf Prototypseite, Rolle <code>+type</code> mit Multiplizität <code>1</code> auf Typseite).\n</li><li><code>PortPrototype2</code> («ARPrototype»): Explizit am <code>ComponentPrototype</code> modellierter Port-Prototyp, angebunden über eine Komposition mit Rolle <code>+port</code> und Kardinalität <code>*</code>.\n</li><li><code>ConnectorPrototype</code> («ARPrototype»): Verbindungs-Prototyp. Er referenziert direkt über eine gerichtete Assoziation <code>+port</code> mit Kardinalität <code>2</code> die Instanz <code>PortPrototype2</code>. Zusätzlich existiert eine gestrichelte Abhängigkeitsbeziehung <code>«instanceRef»</code> mit Rolle <code>+port</code> und Multiplizität <code>2</code> auf <code>PortPrototype</code>.\n</li><li>Invariante (<code>«Invariant»</code>): Gekoppelt an <code>PortPrototype2</code> mit der Bedingung <code>{&quot;ports of component prototype type must be consistent with ports of corresponding type&quot;}</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Architektur; kein dynamischer Sequenzablauf oder Laufzeitverhalten spezifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine Entwurfsvariante (Alternative) für das AUTOSAR-Metamodell dar, bei der Prototypen eigene, explizite Port-Prototyp-Instanzen (<code>PortPrototype2</code>) halten, anstatt Ports rein über Kontextpfade und Instanzreferenzen auf Typ-Ports abzubilden. Werkzeugentwickler und Modellierer müssen die Invariante beachten, wonach die an <code>ComponentPrototype</code> instanziierten Port-Prototypen zwingend konsistent zu den über <code>«isOfType»</code> assoziierten <code>PortPrototype</code>-Elementen des <code>ComponentType</code> gehalten werden müssen. Der Konnektor verbindet unmittelbar zwei <code>PortPrototype2</code>-Elemente und referenziert die typseitigen Ports via <code>«instanceRef»</code>.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-81e9948e5f9197f4", "to": "FIG-06f17b44c95970be", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-06f17b44c95970be", "to": "FIG-688bc7d97c331ceb", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-688bc7d97c331ceb", "to": "FIG-cb5e27a61dd5666b", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
